-- Questions générées restées en attente lors des premiers tris (Culture générale, Sport, Cinéma),
-- repassées après dédoublonnage et un tri Gemini indulgent : seules les questions fausses, ambiguës,
-- absurdes, datées ou en double ont été écartées. Rejouable : un sourceId déjà présent est ignoré.
INSERT INTO "Question" ("id", "sourceId", "questionEn", "questionFr", "answersEn", "answersFr", "correctIndex", "category", "difficulty", "createdAt") VALUES
    (gen_random_uuid()::text, 'gen-6e2407a8fdd06726', 'Claude Chabrol''s film "Le Beau Serge" was shot entirely in the city of Paris.', 'Le film « Le Beau Serge » de Claude Chabrol a été entièrement tourné dans la ville de Paris.', '["True", "False"]'::jsonb, '["Vrai", "Faux"]'::jsonb, 1, 'Film', 'medium', CURRENT_TIMESTAMP),
    (gen_random_uuid()::text, 'gen-fd293e00d8bcc1f5', 'From which French film magazine did directors like François Truffaut and Jean-Luc Godard emerge?', 'De quelle revue de cinéma française sont issus des réalisateurs comme François Truffaut et Jean-Luc Godard ?', '["L''Écran fantastique", "Positif", "Cahiers du cinéma", "Cinéma"]'::jsonb, '["L''Écran fantastique", "Positif", "Les Cahiers du cinéma", "Cinéma"]'::jsonb, 2, 'Film', 'easy', CURRENT_TIMESTAMP),
    (gen_random_uuid()::text, 'gen-62c0372132e74662', 'In the film "Contempt", Brigitte Bardot wears a brown wig in a scene to evoke the look of Anna Karina.', 'Dans le film « Le Mépris », Brigitte Bardot porte une perruque brune dans une scène pour évoquer l''allure d''Anna Karina.', '["True", "False"]'::jsonb, '["Vrai", "Faux"]'::jsonb, 0, 'Film', 'hard', CURRENT_TIMESTAMP),
    (gen_random_uuid()::text, 'gen-25a2bebb9b314734', 'In "Breathless", Jean Seberg represents the classic, hyper-feminine standard of 1950s cinema.', 'Dans « À bout de souffle », Jean Seberg représente le standard classique et hyper-féminin du cinéma des années 1950.', '["True", "False"]'::jsonb, '["Vrai", "Faux"]'::jsonb, 1, 'Film', 'medium', CURRENT_TIMESTAMP),
    (gen_random_uuid()::text, 'gen-2d469d5ae81e7ad5', 'Stanley Kubrick graduated from university with a degree in photography.', 'Stanley Kubrick a obtenu un diplôme universitaire en photographie.', '["True", "False"]'::jsonb, '["Vrai", "Faux"]'::jsonb, 1, 'Film', 'medium', CURRENT_TIMESTAMP),
    (gen_random_uuid()::text, 'gen-00470bccbb17f4b0', 'In which city was Stanley Kubrick born?', 'Dans quelle ville Stanley Kubrick est-il né ?', '["London", "Chicago", "Los Angeles", "New York City"]'::jsonb, '["Londres", "Chicago", "Los Angeles", "New York"]'::jsonb, 3, 'Film', 'easy', CURRENT_TIMESTAMP),
    (gen_random_uuid()::text, 'gen-9174180d169469a3', 'For which magazine did Stanley Kubrick work as an apprentice and staff photographer starting in 1946?', 'Pour quel magazine Stanley Kubrick a-t-il travaillé comme apprenti et photographe permanent à partir de 1946 ?', '["Life", "Look", "Vogue", "Time"]'::jsonb, '["Life", "Look", "Vogue", "Time"]'::jsonb, 1, 'Film', 'hard', CURRENT_TIMESTAMP),
    (gen_random_uuid()::text, 'gen-96d0e063070ba3e4', 'Stanley Kubrick''s first feature film, ''Fear and Desire'', was originally intended to be a silent film.', 'Le premier long-métrage de Stanley Kubrick, ''Fear and Desire'', devait initialement être un film muet.', '["True", "False"]'::jsonb, '["Vrai", "Faux"]'::jsonb, 0, 'Film', 'hard', CURRENT_TIMESTAMP),
    (gen_random_uuid()::text, 'gen-1e861775eda0ecd4', 'Which filmmaker did Stanley Kubrick describe as America''s ''best director'' during his early career?', 'Quel cinéaste Stanley Kubrick considérait-il comme le « meilleur réalisateur » d''Amérique au début de sa carrière ?', '["John Ford", "Sergei Eisenstein", "Elia Kazan", "Max Ophüls"]'::jsonb, '["John Ford", "Sergei Eisenstein", "Elia Kazan", "Max Ophüls"]'::jsonb, 2, 'Film', 'hard', CURRENT_TIMESTAMP),
    (gen_random_uuid()::text, 'gen-d70c16462dc25c13', 'Kubrick''s first documentary, ''Day of the Fight'', was a financial loss, costing more to produce than its selling price.', 'Le premier documentaire de Kubrick, ''Day of the Fight'', a été une perte financière, coûtant plus cher à produire qu''il n''a été vendu.', '["True", "False"]'::jsonb, '["Vrai", "Faux"]'::jsonb, 1, 'Film', 'hard', CURRENT_TIMESTAMP),
    (gen_random_uuid()::text, 'gen-fa6bb1085160370f', 'Kubrick''s uncle Martin Perveler, who invested $9,000 in ''Fear and Desire'', was a professional Hollywood producer.', 'L''oncle de Kubrick, Martin Perveler, qui a investi 9 000 $ dans ''Fear and Desire'', était un producteur professionnel d''Hollywood.', '["True", "False"]'::jsonb, '["Vrai", "Faux"]'::jsonb, 1, 'Film', 'hard', CURRENT_TIMESTAMP),
    (gen_random_uuid()::text, 'gen-d28e9f9f375c322b', 'What major artistic limitation did Hayao Miyazaki face when he first aspired to become a manga artist?', 'Quelle difficulté artistique majeure Hayao Miyazaki a-t-il rencontrée lorsqu''il a voulu devenir dessinateur de manga ?', '["He struggled to write dialogue", "He was unable to draw people", "He could not draw military vehicles", "He was unable to use color"]'::jsonb, '["Il avait du mal à écrire des dialogues", "Il n''arrivait pas à dessiner des personnages", "Il n''arrivait pas à dessiner des véhicules militaires", "Il était incapable d''utiliser la couleur"]'::jsonb, 1, 'Film', 'medium', CURRENT_TIMESTAMP),
    (gen_random_uuid()::text, 'gen-c52be7816d8564fe', 'Which film sparked Hayao Miyazaki''s interest in animation during his high school years?', 'Quel film a éveillé l''intérêt de Hayao Miyazaki pour l''animation lorsqu''il était au lycée ?', '["Gulliver''s Travels Beyond the Moon", "Doggie March", "The White Snake Enchantress", "The Snow Queen"]'::jsonb, '["Les Voyages de Gulliver au-delà de la Lune", "Doggie March", "Le Serpent blanc", "La Reine des neiges"]'::jsonb, 2, 'Film', 'medium', CURRENT_TIMESTAMP),
    (gen_random_uuid()::text, 'gen-4269c4788b490365', 'Hayao Miyazaki majored in animation and fine arts during his university studies.', 'Hayao Miyazaki s''est spécialisé en animation et en beaux-arts durant ses études universitaires.', '["True", "False"]'::jsonb, '["Vrai", "Faux"]'::jsonb, 1, 'Film', 'medium', CURRENT_TIMESTAMP),
    (gen_random_uuid()::text, 'gen-bdaf93548ee7c2f3', 'Which university club did Miyazaki join because it was the closest equivalent to a comics club at the time?', 'Quel club universitaire Miyazaki a-t-il rejoint car c''était l''équivalent le plus proche d''un club de bande dessinée à l''époque ?', '["Political Debate Society", "Film Appreciation Circle", "Classical Art Association", "Children''s Literature Research Club"]'::jsonb, '["Société de débat politique", "Cercle d''appréciation du cinéma", "Association d''art classique", "Club de recherche sur la littérature enfantine"]'::jsonb, 3, 'Film', 'hard', CURRENT_TIMESTAMP),
    (gen_random_uuid()::text, 'gen-ae0ae6aefdfb2d25', 'A screening of the animated film "The Snow Queen" in 1964 convinced Miyazaki to stay in the animation industry when he was doubting his career.', 'Une projection du film d''animation « La Reine des neiges » en 1964 a convaincu Miyazaki de poursuivre sa carrière alors qu''il doutait de sa voie.', '["True", "False"]'::jsonb, '["Vrai", "Faux"]'::jsonb, 0, 'Film', 'medium', CURRENT_TIMESTAMP),
    (gen_random_uuid()::text, 'gen-f30e1069c13ade05', 'Why did Hayao Miyazaki destroy a large portion of his early manga drawings?', 'Pourquoi Hayao Miyazaki a-t-il détruit une grande partie de ses premiers dessins de manga ?', '["A publisher rejected them and told him to start over", "He felt he was copying Osamu Tezuka''s style too closely", "He wanted to focus entirely on drawing military vehicles", "His art teacher advised him that they were of poor quality"]'::jsonb, '["Un éditeur les avait refusés en lui disant de tout recommencer", "Il estimait qu''il copiait trop le style d''Osamu Tezuka", "Il voulait se consacrer uniquement au dessin de véhicules militaires", "Son professeur d''art lui avait dit qu''ils étaient de mauvaise qualité"]'::jsonb, 1, 'Film', 'medium', CURRENT_TIMESTAMP),
    (gen_random_uuid()::text, 'gen-5e8ff2db17cbfa2a', 'Hayao Miyazaki started his career at Toei Doga directly as a film director.', 'Hayao Miyazaki a commencé sa carrière chez Toei Doga directement en tant que réalisateur de films.', '["True", "False"]'::jsonb, '["Vrai", "Faux"]'::jsonb, 1, 'Film', 'easy', CURRENT_TIMESTAMP),
    (gen_random_uuid()::text, 'gen-3ca867988d219e38', 'Which animated television series was Hayao Miyazaki''s directorial debut?', 'Quelle série télévisée d''animation constitue le premier travail de réalisation de Hayao Miyazaki ?', '["Heidi, Girl of the Alps", "Lupin the Third Part I", "Future Boy Conan", "3000 Leagues in Search of Mother"]'::jsonb, '["Heidi", "Lupin III", "Future Boy Conan", "3000 lieues en quête de mère"]'::jsonb, 2, 'Film', 'medium', CURRENT_TIMESTAMP),
    (gen_random_uuid()::text, 'gen-58d202b2c6e726d2', 'Hayao Miyazaki published the manga ''People of the Desert'' under the pseudonym Akitsu Saburō.', 'Hayao Miyazaki a publié le manga ''People of the Desert'' sous le pseudonyme Akitsu Saburō.', '["True", "False"]'::jsonb, '["Vrai", "Faux"]'::jsonb, 0, 'Film', 'hard', CURRENT_TIMESTAMP),
    (gen_random_uuid()::text, 'gen-8e9ba8c02cb0cb32', 'To which country did Hayao Miyazaki travel for his first trip outside of Japan?', 'Dans quel pays Hayao Miyazaki s''est-il rendu pour son tout premier voyage hors du Japon ?', '["Switzerland", "Argentina", "Italy", "Sweden"]'::jsonb, '["Suisse", "Argentine", "Italie", "Suède"]'::jsonb, 3, 'Film', 'hard', CURRENT_TIMESTAMP),
    (gen_random_uuid()::text, 'gen-9bca02d1a0d4a3bd', 'Hayao Miyazaki traveled to Italy to research for the production of the series Heidi, Girl of the Alps.', 'Hayao Miyazaki s''est rendu en Italie pour effectuer des recherches pour la production de la série Heidi.', '["True", "False"]'::jsonb, '["Vrai", "Faux"]'::jsonb, 1, 'Film', 'medium', CURRENT_TIMESTAMP),
    (gen_random_uuid()::text, 'gen-53bdbab235fd785d', 'Why did Hayao Miyazaki leave Toei Animation in 1971?', 'Pourquoi Hayao Miyazaki a-t-il quitté Toei Animation en 1971 ?', '["An offer to join Disney", "Lack of creative prospects and autonomy", "Bankruptcy of the studio", "A desire to retire early"]'::jsonb, '["Offre pour rejoindre Disney", "Manque de perspectives créatives et d''autonomie", "Faillite du studio", "Désir de prendre sa retraite"]'::jsonb, 1, 'Film', 'medium', CURRENT_TIMESTAMP),
    (gen_random_uuid()::text, 'gen-3b4ba533cd8c7dee', 'Which animal inspired the creation of the ''Panda! Go, Panda!'' shorts?', 'Quel animal a inspiré la création des courts-métrages ''Panda! Go, Panda!'' ?', '["Raccoon", "Bear", "Monkey", "Panda"]'::jsonb, '["Raton laveur", "Ours", "Singe", "Panda"]'::jsonb, 3, 'Film', 'easy', CURRENT_TIMESTAMP),
    (gen_random_uuid()::text, 'gen-dff6a24f46bbb518', 'Nippon Animation was formed after the split of the company Zuiyō Eizō.', 'Nippon Animation a été formé après la scission de la société Zuiyō Eizō.', '["True", "False"]'::jsonb, '["Vrai", "Faux"]'::jsonb, 0, 'Film', 'hard', CURRENT_TIMESTAMP),
    (gen_random_uuid()::text, 'gen-8ed55be77518421e', 'Which of these activities did young Louis de Funès enjoy during his boarding school years?', 'Laquelle de ces activités Louis de Funès appréciait-il durant ses années de pensionnat ?', '["Horse riding", "Writing poetry", "Fishing", "Playing piano"]'::jsonb, '["Faire de l''équitation", "Écrire de la poésie", "La pêche", "Jouer du piano"]'::jsonb, 2, 'Film', 'medium', CURRENT_TIMESTAMP),
    (gen_random_uuid()::text, 'gen-de61d8b48a31a8d2', 'In 1926, in which comic opera did Louis de Funès make his theatrical debut?', 'En 1926, dans quel opéra-comique Louis de Funès fait-il ses débuts théâtraux ?', '["La Grande Vadrouille", "Le Petit Baigneur", "Le Royal Dindon", "Le Gendarme de Saint-Tropez"]'::jsonb, '["La Grande Vadrouille", "Le Petit Baigneur", "Le Royal Dindon", "Le Gendarme de Saint-Tropez"]'::jsonb, 2, 'Film', 'hard', CURRENT_TIMESTAMP),
    (gen_random_uuid()::text, 'gen-22add875e5fe4ffa', 'Louis de Funès successfully completed his training at the furrier school.', 'Louis de Funès a terminé avec succès sa formation à l''école de la fourrure.', '["True", "False"]'::jsonb, '["Vrai", "Faux"]'::jsonb, 1, 'Film', 'medium', CURRENT_TIMESTAMP),
    (gen_random_uuid()::text, 'gen-0ed31bcc0c68a3a6', 'Which future famous cinematographer was a classmate of Louis de Funès at the ETPC?', 'Quel futur célèbre directeur de la photographie était le condisciple de Louis de Funès à l''ETPC ?', '["Raoul Coutard", "Sacha Vierny", "Ghislain Cloquet", "Henri Decaë"]'::jsonb, '["Raoul Coutard", "Sacha Vierny", "Ghislain Cloquet", "Henri Decaë"]'::jsonb, 3, 'Film', 'hard', CURRENT_TIMESTAMP),
    (gen_random_uuid()::text, 'gen-8984321a2693ed5a', '''Les Visiteurs du mercredi'' was a science fiction novel written in 1981.', '''Les Visiteurs du mercredi'' était un roman de science-fiction écrit en 1981.', '["True", "False"]'::jsonb, '["Vrai", "Faux"]'::jsonb, 1, 'Film', 'medium', CURRENT_TIMESTAMP),
    (gen_random_uuid()::text, 'gen-6656972c4656edeb', 'In which English county were the Harry Potter films primarily produced at Leavesden Studios?', 'Dans quel comté anglais les films Harry Potter ont-ils été principalement produits, aux studios Leavesden ?', '["Hertfordshire", "London", "Oxfordshire", "Surrey"]'::jsonb, '["Hertfordshire", "Londres", "Oxfordshire", "Surrey"]'::jsonb, 0, 'Film', 'medium', CURRENT_TIMESTAMP),
    (gen_random_uuid()::text, 'gen-0c378eb0a0053062', 'Which director of the first two Harry Potter films noted that the movies would get ''progressively darker''?', 'Quel réalisateur des deux premiers films Harry Potter a noté que les films deviendraient « progressivement plus sombres » ?', '["Chris Columbus", "David Yates", "Alfonso Cuarón", "Mike Newell"]'::jsonb, '["Chris Columbus", "David Yates", "Alfonso Cuarón", "Mike Newell"]'::jsonb, 0, 'Film', 'easy', CURRENT_TIMESTAMP),
    (gen_random_uuid()::text, 'gen-13ec49df0641080b', 'David Yates is the only director to have helmed more than one Harry Potter film since Chris Columbus.', 'David Yates est le seul réalisateur à avoir dirigé plus d''un film Harry Potter depuis Chris Columbus.', '["True", "False"]'::jsonb, '["Vrai", "Faux"]'::jsonb, 0, 'Film', 'medium', CURRENT_TIMESTAMP),
    (gen_random_uuid()::text, 'gen-2379cb839cb5b4c7', 'Which religious order ran the grammar school Hitchcock attended in Stamford Hill?', 'Quel ordre religieux dirigeait l''école fréquentée par Hitchcock à Stamford Hill ?', '["Dominicans", "Jesuits", "Franciscans", "Benedictines"]'::jsonb, '["Dominicains", "Jésuites", "Franciscains", "Bénédictins"]'::jsonb, 1, 'Film', 'hard', CURRENT_TIMESTAMP),
    (gen_random_uuid()::text, 'gen-79f8f6c66589f09f', 'Steven Spielberg was born in the state of California.', 'Steven Spielberg est né dans l''État de Californie.', '["True", "False"]'::jsonb, '["Vrai", "Faux"]'::jsonb, 1, 'Film', 'medium', CURRENT_TIMESTAMP),
    (gen_random_uuid()::text, 'gen-005bbc69ca03c8c5', 'What was the profession of Steven Spielberg''s mother, Leah Adler?', 'Quel était le métier de Leah Adler, la mère de Steven Spielberg ?', '["Film producer", "Concert pianist", "Rabbi", "Electrical engineer"]'::jsonb, '["Productrice de cinéma", "Pianiste de concert", "Rabbin", "Ingénieur en électricité"]'::jsonb, 1, 'Film', 'medium', CURRENT_TIMESTAMP),
    (gen_random_uuid()::text, 'gen-8ad72194a83242a6', 'Which film did Steven Spielberg''s parents take him to see, thinking it was a circus trip?', 'Quel film les parents de Steven Spielberg l''ont-ils emmené voir, alors qu''il pensait aller au cirque ?', '["The Birds", "Pinocchio", "Fantasia", "The Greatest Show on Earth"]'::jsonb, '["Les Oiseaux", "Pinocchio", "Fantasia", "Sous le plus grand chapiteau du monde"]'::jsonb, 3, 'Film', 'medium', CURRENT_TIMESTAMP),
    (gen_random_uuid()::text, 'gen-f37d1ca3a68d4f65', 'What is Quentin Tarantino''s primary profession?', 'Quelle est la profession principale de Quentin Tarantino ?', '["Filmmaker", "Musician", "Architect", "Journalist"]'::jsonb, '["Réalisateur", "Musicien", "Architecte", "Journaliste"]'::jsonb, 0, 'Film', 'easy', CURRENT_TIMESTAMP),
    (gen_random_uuid()::text, 'gen-b9f72b686d55df5e', 'Which short film did John Lasseter premiere to demonstrate the Pixar Image Computer''s capabilities?', 'Quel court-métrage John Lasseter a-t-il présenté pour démontrer les capacités du Pixar Image Computer ?', '["The Adventures of André and Wally B.", "Luxo Jr.", "Tin Toy", "Red''s Dream"]'::jsonb, '["Les Aventures d''André et Wally B.", "Luxo Jr.", "Tin Toy", "Red''s Dream"]'::jsonb, 1, 'Film', 'medium', CURRENT_TIMESTAMP),
    (gen_random_uuid()::text, 'gen-f23c9258a03a4418', 'In You Only Live Twice, Blofeld intends to trigger World War III by framing the United States.', 'Dans On ne vit que deux fois, Blofeld a l''intention de déclencher la Troisième Guerre mondiale en piégeant les États-Unis.', '["True", "False"]'::jsonb, '["Vrai", "Faux"]'::jsonb, 1, 'Film', 'hard', CURRENT_TIMESTAMP),
    (gen_random_uuid()::text, 'gen-619b0ba281629c05', 'In Diamonds Are Forever, the diamond smuggling ring leads Bond to a laboratory owned by Willard Whyte.', 'Dans Les diamants sont éternels, le réseau de contrebande de diamants conduit Bond vers un laboratoire appartenant à Willard Whyte.', '["True", "False"]'::jsonb, '["Vrai", "Faux"]'::jsonb, 0, 'Film', 'hard', CURRENT_TIMESTAMP),
    (gen_random_uuid()::text, 'gen-bbb89693ae7bf2e3', 'What amount did Paramount Pictures pay to acquire the rights to the novel The Godfather?', 'Quel montant Paramount Pictures a-t-il déboursé pour acquérir les droits du roman Le Parrain ?', '["1 million dollars", "250,000 dollars", "500,000 dollars", "80,000 dollars"]'::jsonb, '["1 million de dollars", "250 000 dollars", "500 000 dollars", "80 000 dollars"]'::jsonb, 3, 'Film', 'hard', CURRENT_TIMESTAMP),
    (gen_random_uuid()::text, 'gen-145afe8597f49d3d', 'In which year was The Godfather selected for preservation in the U.S. National Film Registry?', 'En quelle année Le Parrain a-t-il été sélectionné pour être conservé au National Film Registry ?', '["1984", "1990", "1995", "1972"]'::jsonb, '["1984", "1990", "1995", "1972"]'::jsonb, 1, 'Film', 'hard', CURRENT_TIMESTAMP),
    (gen_random_uuid()::text, 'gen-20b6c2edbd146295', 'What trade does Vito Corleone agree to allow in exchange for peace between the New York families?', 'Quel commerce Vito Corleone accepte-t-il de tolérer en échange de la paix entre les familles new-yorkaises ?', '["Prostitution rings", "Controlled drug trade", "Illegal arms trafficking", "Construction labor unions"]'::jsonb, '["Réseaux de prostitution", "Commerce de drogue contrôlé", "Trafic d''armes illégal", "Syndicats du bâtiment"]'::jsonb, 1, 'Film', 'medium', CURRENT_TIMESTAMP),
    (gen_random_uuid()::text, 'gen-30b886e8002e32ca', 'What career did Luc Besson originally plan to pursue before an accident forced him to change paths?', 'Quelle carrière Luc Besson se destinait-il à suivre avant qu''un accident ne l''oblige à changer de voie ?', '["Oceanographer", "Marine biologist", "Professional diver", "Delphinologist"]'::jsonb, '["Océanographe", "Biologiste marin", "Plongeur professionnel", "Delphinologue"]'::jsonb, 3, 'Film', 'medium', CURRENT_TIMESTAMP),
    (gen_random_uuid()::text, 'gen-6319700c8e57dfdc', 'Which 1962 film inspired the aesthetic of Luc Besson''s debut feature, Le Dernier Combat?', 'Quel film de 1962 a inspiré l''esthétique du premier long métrage de Luc Besson, Le Dernier Combat ?', '["La Jetée", "Alphaville", "Les Quatre Cents Coups", "Hiroshima mon amour"]'::jsonb, '["La Jetée", "Alphaville", "Les Quatre Cents Coups", "Hiroshima mon amour"]'::jsonb, 0, 'Film', 'hard', CURRENT_TIMESTAMP),
    (gen_random_uuid()::text, 'gen-d7dba714ea3190ee', 'Who coined the term ''cinéma du look'' to describe the visual style of directors like Luc Besson?', 'Qui a forgé le terme « cinéma du look » pour décrire le style visuel de réalisateurs comme Luc Besson ?', '["Raphaël Bassan", "Jean-Jacques Beineix", "Leos Carax", "François Truffaut"]'::jsonb, '["Raphaël Bassan", "Jean-Jacques Beineix", "Leos Carax", "François Truffaut"]'::jsonb, 0, 'Film', 'hard', CURRENT_TIMESTAMP),
    (gen_random_uuid()::text, 'gen-15e3f25202f9c426', 'Luc Besson boycotted the 20th César Awards because he disagreed with the winner of the Best Foreign Film award.', 'Luc Besson a boycotté la 20e cérémonie des César car il était en désaccord avec le film récompensé du César du meilleur film étranger.', '["True", "False"]'::jsonb, '["Vrai", "Faux"]'::jsonb, 0, 'Film', 'hard', CURRENT_TIMESTAMP),
    (gen_random_uuid()::text, 'gen-d4ffb9b750ab089b', 'Which director was Jean Gabin supposed to work with on the project ''A Thief in the Night'' before he decided to join the war effort?', 'Avec quel réalisateur Jean Gabin devait-il collaborer sur le projet ''A Thief in the Night'' avant de choisir de s''engager dans la guerre ?', '["Julien Duvivier", "Marcel Carné", "Henri Bernstein", "Jean Renoir"]'::jsonb, '["Julien Duvivier", "Marcel Carné", "Henri Bernstein", "Jean Renoir"]'::jsonb, 3, 'Film', 'hard', CURRENT_TIMESTAMP),
    (gen_random_uuid()::text, 'gen-c42393225aa3a8d4', 'True or false: Jean Gabin turned down the lead role in ''Les Portes de la nuit'' because Marlene Dietrich refused to play the daughter of a collaborator.', 'Vrai ou Faux : Jean Gabin a renoncé au rôle principal dans ''Les Portes de la nuit'' car Marlene Dietrich refusait d''incarner la fille d''un collaborateur.', '["True", "False"]'::jsonb, '["Vrai", "Faux"]'::jsonb, 0, 'Film', 'hard', CURRENT_TIMESTAMP),
    (gen_random_uuid()::text, 'gen-16a02b314c391297', 'What was the name of the tank commanded by Jean Gabin while serving in the 2nd Armored Division?', 'Quel était le nom du char commandé par Jean Gabin lorsqu''il servait au sein de la 2e division blindée ?', '["Tampico", "Souffleur II", "Miroir", "L''Imposteur"]'::jsonb, '["Tampico", "Souffleur II", "Miroir", "L''Imposteur"]'::jsonb, 1, 'Film', 'hard', CURRENT_TIMESTAMP),
    (gen_random_uuid()::text, 'gen-e20249bf3a5ed840', 'Which Jean Gabin film, co-starring Marlene Dietrich, was unfairly labeled a commercial flop despite having over 2 million admissions?', 'Quel film de Jean Gabin, avec Marlene Dietrich, a été injustement qualifié d''échec commercial alors qu''il a réalisé plus de 2 millions d''entrées ?', '["Miroir", "La Marie du port", "Au-delà des grilles", "Martin Roumagnac"]'::jsonb, '["Miroir", "La Marie du port", "Au-delà des grilles", "Martin Roumagnac"]'::jsonb, 3, 'Film', 'hard', CURRENT_TIMESTAMP),
